#include <iostream>
#include <optional>
#include <string>
#include <variant>
#include <vector>

struct User { int id; std::string name; };

std::optional<User> find_user(const std::vector<User>& users, int id) {
    for (const auto& u : users) if (u.id == id) return u;
    return std::nullopt;                                   // no sentinel User.
}

template <class... Fs> struct overloaded : Fs... { using Fs::operator()...; };

using Setting = std::variant<int, bool, std::string>;

void print(const Setting& s) {
    std::visit(overloaded{                                 // every alternative handled.
        [](int n)                { std::cout << "number " << n << '\n'; },
        [](bool b)               { std::cout << (b ? "on" : "off") << '\n'; },
        [](const std::string& t) { std::cout << "text " << t << '\n'; },
    }, s);
}

int main() {
    std::vector<User> users{{1, "Asha"}};
    if (auto u = find_user(users, 2)) std::cout << u->name << '\n';
    else std::cout << "no user\n";                         // checked before *.
    print(Setting{42});
    print(Setting{std::string("dark")});
}
```

